-- =================================================================================
-- BlueKhata — Complete Production Database Installer
-- Generated by reverse-engineering the Flutter project (lib/**) against the
-- existing supabase/migrations/0001–0004 SQL, so this file is the single
-- source of truth going forward.
--
-- SAFE TO RE-RUN: every statement is idempotent (create/drop-if-exists),
-- so pasting this into the Supabase SQL Editor and pressing RUN multiple
-- times will not error or duplicate objects.
--
-- WHAT CHANGED VS THE ORIGINAL 4 MIGRATIONS
--   1. public.users -> public.profiles (RENAMED)
--      Flutter's AuthRepository (lib/features/authentication/data/
--      repositories/auth_repository.dart) reads/writes a table literally
--      named `profiles` with columns `id`, `full_name`, `phone`. The
--      original migrations only created `public.users` (columns
--      `display_name`, no `full_name`) — every call from the app would
--      have failed with "relation public.profiles does not exist" or,
--      after a naive add-a-table fix, left two disconnected user tables.
--      Fix: the profile table is now named `profiles`, its name column is
--      `full_name` (matching the Flutter upsert payload exactly), and
--      every foreign key that used to point at `public.users(id)` now
--      points at `public.profiles(id)`. This is the ONLY breaking
--      mismatch found between the app and the database — see
--      flutter_database_compatibility_report.md for the full audit.
--   2. Everything else (businesses, business_members, customers,
--      ledger_entries, cashbook_entries, bank_accounts, bank_transactions,
--      categories, products, inventory_logs, invoices, invoice_items,
--      staff, attendance, salary, reminders, notifications, announcements,
--      banners, settings, audit_logs, deleted_records, backup_history)
--      already matched the Flutter code exactly and is carried over
--      unchanged in structure, just renumbered into one file.
--   3. Additive, non-breaking extras requested by the install spec that
--      the Flutter code does not yet call, but which the schema needs to
--      be "complete": a `payment_methods` lookup table + seed data,
--      storage buckets/policies for every *_url column, and two
--      dashboard views. These are clearly marked "ADDITIVE" below and
--      cannot break any existing query because nothing in lib/ references
--      them yet.
-- =================================================================================

-- =================================================================================
-- SECTION 0 — EXTENSIONS
-- =================================================================================
create extension if not exists "uuid-ossp";
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;

-- =================================================================================
-- SECTION 1 — SHARED FUNCTIONS (defined early; referenced by triggers below)
-- =================================================================================

-- Generic updated_at maintenance, reused by every table that has the column.
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- =================================================================================
-- SECTION 2 — PROFILES  (renamed from `users` to match Flutter's `profiles` calls)
-- =================================================================================
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  phone text,
  avatar_url text,
  preferred_language text default 'en',
  role text not null default 'business_owner'
    check (role in ('super_admin','business_owner','manager','cashier','staff','viewer')),
  is_blocked boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists trg_profiles_touch on public.profiles;
create trigger trg_profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- ADDITIVE (safety net, does not conflict with Flutter's own upsert-on-signup):
-- auto-create a bare profile row whenever a new auth.users row appears, so a
-- profile always exists even for users created outside signUp() (magic link,
-- OAuth, admin invite, etc). Flutter's ensureProfile()/upsert still works
-- unchanged — it will simply update the row this trigger already created.
create or replace function public.handle_new_auth_user()
returns trigger language plpgsql security definer as $$
begin
  insert into public.profiles (id, full_name, phone)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', ''), null)
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists trg_auth_user_created on auth.users;
create trigger trg_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_auth_user();

alter table public.profiles enable row level security;

drop policy if exists profiles_select_self on public.profiles;
create policy profiles_select_self on public.profiles
  for select using (id = auth.uid());
drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles
  for update using (id = auth.uid());
drop policy if exists profiles_insert_self on public.profiles;
create policy profiles_insert_self on public.profiles
  for insert with check (id = auth.uid());

