alter table public.business_members enable row level security;

-- helper: is the current user a member (any role) of a business?
-- Defined after businesses/business_members exist, before it's used in policies.
create or replace function public.is_business_member(target_business_id uuid)
returns boolean language sql stable as $$
  select exists (
    select 1 from public.businesses b
    where b.id = target_business_id and b.owner_id = auth.uid()
  ) or exists (
    select 1 from public.business_members m
    where m.business_id = target_business_id
      and m.user_id = auth.uid()
      and m.status = 'active'
  );
$$;

-- businesses policies (declared here, after is_business_member exists)
drop policy if exists businesses_select on public.businesses;
create policy businesses_select on public.businesses
  for select using (public.is_business_member(id));
drop policy if exists businesses_insert on public.businesses;
create policy businesses_insert on public.businesses
  for insert with check (owner_id = auth.uid());
drop policy if exists businesses_update on public.businesses;
create policy businesses_update on public.businesses
  for update using (owner_id = auth.uid());
drop policy if exists businesses_delete on public.businesses;
create policy businesses_delete on public.businesses
  for delete using (owner_id = auth.uid());

drop policy if exists business_members_select on public.business_members;
create policy business_members_select on public.business_members
  for select using (public.is_business_member(business_id));
drop policy if exists business_members_write on public.business_members;
create policy business_members_write on public.business_members
  for all using (
    exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid())
  );

