-- =================================================================================
-- SECTION 16 — ADDITIVE: PAYMENT_METHODS LOOKUP TABLE
-- Not called by any current Flutter code (no repository references it yet),
-- but included because it's a standard companion to cashbook/bank/invoice
-- modules and was explicitly requested in the install spec ("Default Payment
-- Methods"). Safe to ignore until a payments feature is built — it cannot
-- break any existing query.
-- =================================================================================
create table if not exists public.payment_methods (
  id uuid primary key default uuid_generate_v4(),
  business_id uuid references public.businesses(id) on delete cascade,
  name text not null,
  is_default boolean not null default false,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique(business_id, name)
);

alter table public.payment_methods enable row level security;
drop policy if exists payment_methods_select on public.payment_methods;
create policy payment_methods_select on public.payment_methods
  for select using (business_id is null or public.is_business_member(business_id));
drop policy if exists payment_methods_write on public.payment_methods;
create policy payment_methods_write on public.payment_methods
  for all using (business_id is not null and public.is_business_member(business_id));

-- =================================================================================
-- SECTION 17 — ADDITIVE: DASHBOARD VIEWS
-- Read-only convenience views for the reports/analytics module mentioned in
-- README's "Not yet built" list. Inherit RLS from their base tables
-- automatically (views run with the querying user's permissions here since
-- they are not security definer).
-- =================================================================================
create or replace view public.business_dashboard_summary as
select
  b.id as business_id,
  b.name as business_name,
  b.currency,
  count(distinct c.id) filter (where c.is_deleted = false) as total_customers,
  coalesce(sum(c.current_balance) filter (where c.is_deleted = false and c.current_balance > 0), 0) as total_receivable,
  coalesce(sum(abs(c.current_balance)) filter (where c.is_deleted = false and c.current_balance < 0), 0) as total_payable
from public.businesses b
left join public.customers c on c.business_id = b.id
where b.is_deleted = false
group by b.id, b.name, b.currency;

create or replace view public.daily_ledger_summary as
select
  le.business_id,
  date_trunc('day', le.entry_date) as entry_day,
  sum(le.amount) filter (where le.type = 'credit') as total_credit,
  sum(le.amount) filter (where le.type = 'debit') as total_debit
from public.ledger_entries le
where le.is_deleted = false
group by le.business_id, date_trunc('day', le.entry_date);

-- =================================================================================
-- SECTION 18 — ADDITIVE: STORAGE BUCKETS + STORAGE POLICIES
-- Inferred from every *_url column in the schema (logo_url, banner_url,
-- image_url, avatar_url, attachment_urls). No .storage/.bucket() call exists
-- in lib/ yet (Flutter currently just stores whatever URL string it is
-- given), so these buckets are provisioned ahead of that integration and are
-- safe no-ops until the app starts uploading files.
-- =================================================================================
insert into storage.buckets (id, name, public)
values
  ('avatars', 'avatars', true),
  ('business-assets', 'business-assets', true),
  ('customer-images', 'customer-images', true),
  ('ledger-attachments', 'ledger-attachments', false),
  ('product-images', 'product-images', true)
on conflict (id) do nothing;

-- Avatars: user manages their own folder (avatars/<uid>/...).
drop policy if exists avatars_read on storage.objects;
create policy avatars_read on storage.objects
  for select using (bucket_id = 'avatars');
drop policy if exists avatars_write on storage.objects;
create policy avatars_write on storage.objects
  for insert with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists avatars_update on storage.objects;
create policy avatars_update on storage.objects
  for update using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists avatars_delete on storage.objects;
create policy avatars_delete on storage.objects
  for delete using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

-- Business-scoped buckets: folder convention <bucket>/<business_id>/..., gated
-- by is_business_member() so only members of that business can read/write.
drop policy if exists business_assets_read on storage.objects;
create policy business_assets_read on storage.objects
  for select using (bucket_id = 'business-assets');
drop policy if exists business_assets_write on storage.objects;
create policy business_assets_write on storage.objects
  for all using (
    bucket_id = 'business-assets'
    and public.is_business_member(((storage.foldername(name))[1])::uuid)
  );

drop policy if exists customer_images_read on storage.objects;
create policy customer_images_read on storage.objects
  for select using (bucket_id = 'customer-images');
drop policy if exists customer_images_write on storage.objects;
create policy customer_images_write on storage.objects
  for all using (
    bucket_id = 'customer-images'
    and public.is_business_member(((storage.foldername(name))[1])::uuid)
  );

drop policy if exists ledger_attachments_rw on storage.objects;
create policy ledger_attachments_rw on storage.objects
  for all using (
    bucket_id = 'ledger-attachments'
    and public.is_business_member(((storage.foldername(name))[1])::uuid)
  );

drop policy if exists product_images_read on storage.objects;
create policy product_images_read on storage.objects
  for select using (bucket_id = 'product-images');
drop policy if exists product_images_write on storage.objects;
create policy product_images_write on storage.objects
  for all using (
    bucket_id = 'product-images'
    and public.is_business_member(((storage.foldername(name))[1])::uuid)
  );

